// Post-export validation: reopen the generated bytes with a parser and check page count and representative edited content.
import type { DocState, Plan } from './types.ts'
import { isChanged } from './plan.ts'

export type Validation = { ok: boolean; pageCount: number; expectedPages: number; checked: number; missing: string[]; leftovers: string[] }
const count = (hay: string, needle: string) => { let n = 0, i = 0; while ((i = hay.indexOf(needle, i)) >= 0) { n++; i += needle.length } return n }
const strip = (s: string) => s.replace(/\s+/g, '')

export async function validateExport(pdfjs: any, bytes: Uint8Array, doc: DocState, plan: Plan): Promise<Validation> {
  const pdf = await pdfjs.getDocument({ data: bytes.slice(), verbosity: 0 }).promise
  try {
    let all = ''
    for (let i = 1; i <= pdf.numPages; i++) {
      const tc = await (await pdf.getPage(i)).getTextContent()
      all += tc.items.map((x: any) => x.str).join('')
    }
    all = strip(all)
    const inEditedBlock = new Set<string>()
    for (const b of doc.blocks ?? []) if (b.included && b.edited) b.lineIds.forEach((i) => inEditedBlock.add(i))
    const current: string[] = []
    const expect: string[] = []
    for (const id of doc.order) {
      const e = doc.els[id]
      if (e.deleted || inEditedBlock.has(id)) continue
      current.push(strip(e.text))
      if (isChanged(e) && !(e.locked && !e.cover && !e.created)) expect.push(strip(e.text))
    }
    for (const b of doc.blocks ?? []) if (b.included && b.edited) { current.push(strip(b.text)); expect.push(strip(b.text)) }
    const cur = current.join('|')
    const missing: string[] = [], leftovers: string[] = []
    for (const t of expect) {
      if (t.length < 2) continue
      // wrapped text is split across items, so test the unbroken head of the string
      const head = t.length > 24 ? t.slice(0, 24) : t
      if (!all.includes(head)) missing.push(t.slice(0, 40))
    }
    const edited = [...doc.order.map((i) => doc.els[i]).filter((e) => !e.created && isChanged(e) && !e.locked && e.originalText !== e.text).map((e) => strip(e.originalText)),
      ...(doc.blocks ?? []).filter((b) => b.included && b.edited).map((b) => strip(b.lineIds.map((i) => doc.els[i].text).join(' ')))]
    for (const o of edited) {
      const head = o.length > 24 ? o.slice(0, 24) : o
      if (head.length >= 6 && count(all, head) > count(cur, head)) leftovers.push(head) // a stale copy of the old text is still in the file
    }
    return { ok: pdf.numPages === plan.pages.length && !missing.length && !leftovers.length, pageCount: pdf.numPages, expectedPages: plan.pages.length, checked: expect.length, missing, leftovers }
  } finally { pdf.destroy?.() }
}
